+        if (where.id) return Promise.resolve(rows.filter((r) => where.id.in.includes(r.id)));
+        // Revalidation read: case-insensitive match on the group's key.
+        const eq = (a: string, b: string) => a.trim().toLowerCase() === b.trim().toLowerCase();
